That it'll compile and run the tests successfully.

**Version info (please complete the following information):**
 - Lombok version: 1.18.6
 - Platform: Java 11.0.2, Ubuntu 16.04

**Additional context**
Here's the code. I think what's causing problems is my build() doesn't return a MockResultSet...some sort of type check/enforcement changes in .4->.6 on that?
```
package com.kessel;

import lombok.Builder;
import lombok.SneakyThrows;

import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;

/**
 * Mocks a SQL ResultSet.
 * Taken from https://github.com/sharfah/java-utils/tree/master/src/test/java/com/sharfah/util/sql
 * After seeing their post on https://www.javacodegeeks.com/2018/09/java-mocking-resultset-using-mockito.html
 *
 * Modified slightly to bring it up to date with current library versions.
 */
public class MockResultSet {

    private final Map<String, Integer> columnIndices;
    private final Object[][] data;
    private int rowIndex;

    @Builder
    private MockResultSet(String[] columnNames, final Object[][] data) {
        if (columnNames != null) {
            this.columnIndices = IntStream.range(0, columnNames.length)
                    .boxed()
                    .collect(Collectors.toMap(
                            k -> columnNames[k],
                            Function.identity(),
                            (a, b) -> {
                                throw new RuntimeException("Duplicate column " + a);
                            },
                            LinkedHashMap::new
                    ));
        } else {
            this.columnIndices = new HashMap<>();
        }
        this.data = data;
        this.rowIndex = -1;
    }

    public static ResultSet empty() {
        return builder().data().build();
    }

    @SuppressWarnings("MethodOnlyUsedFromInnerClass")
    @SneakyThrows
    private ResultSet buildMock() {
        ResultSet rs = mock(ResultSet.class);

        // mock rs.next()
        doAnswer(invocation -> {
            rowIndex++;
            return rowIndex < data.length;
        }).when(rs).next();

        // mock rs.getString(columnName)
        doAnswer(invocation -> {
            String columnName = invocation.getArgument(0);
            Integer columnIndex = columnIndices.get(columnName);
            return data[rowIndex][columnIndex];
        }).when(rs).getString(anyString());

        // mock rs.getString(columnIndex)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return data[rowIndex][index - 1];
        }).when(rs).getString(anyInt());

        // mock rs.getInt(columnName)
        doAnswer(invocation -> {
            String columnName = invocation.getArgument(0);
            Integer columnIndex = columnIndices.get(columnName);
            return data[rowIndex][columnIndex];
        }).when(rs).getInt(anyString());

        // mock rs.getInt(columnIndex)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return data[rowIndex][index - 1];
        }).when(rs).getInt(anyInt());

        // mock rs.getLong(columnName)
        doAnswer(invocation -> {
            String columnName = invocation.getArgument(0);
            int columnIndex = columnIndices.get(columnName);
            return data[rowIndex][columnIndex];
        }).when(rs).getLong(anyString());

        // mock rs.getLong(columnIndex)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return data[rowIndex][index - 1];
        }).when(rs).getLong(anyInt());

        // mock rs.getTimestamp(columnName)
        doAnswer(invocation -> {
            String columnName = invocation.getArgument(0);
            int columnIndex = columnIndices.get(columnName);
            return data[rowIndex][columnIndex];
        }).when(rs).getTimestamp(anyString());

        // mock rs.getTimestamp(columnIndex)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return data[rowIndex][index - 1];
        }).when(rs).getTimestamp(anyInt());

        // mock rs.getObject(columnName)
        doAnswer(invocation -> {
            String columnName = invocation.getArgument(0);
            Integer columnIndex = columnIndices.get(columnName);
            return data[rowIndex][columnIndex];
        }).when(rs).getObject(anyString());

        // mock rs.getObject(columnIndex)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return data[rowIndex][index - 1];
        }).when(rs).getObject(anyInt());

        // mock rs.getObject(columnName, Class)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return data[rowIndex][index - 1];
        }).when(rs).getObject(anyString(), any(Class.class));

        // mock rs.getObject(columnIndex, Class)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return data[rowIndex][index - 1];
        }).when(rs).getObject(anyInt(), any(Class.class));

        ResultSetMetaData rsmd = mock(ResultSetMetaData.class);

        // mock rsmd.getColumnCount()
        doReturn(columnIndices.size()).when(rsmd).getColumnCount();

        // mock rsmd.getColumnName(int)
        doAnswer(invocation -> {
            Integer index = invocation.getArgument(0);
            return columnIndices.keySet().stream().skip(index - 1).findFirst().get();
        }).when(rsmd).getColumnName(anyInt());

        // mock rs.getMetaData()
        doReturn(rsmd).when(rs).getMetaData();

        return rs;
    }

    @SuppressWarnings("unused")
    public static class MockResultSetBuilder {

        public MockResultSetBuilder columnNames(String... s) {
            this.columnNames = s;
            return this;
        }

        public MockResultSetBuilder data(Object[]... o) {
            this.data = o;
            return this;
        }

        public ResultSet build() {
            return new MockResultSet(columnNames, data).buildMock();
        }
    }
}
```

