```java
    private <B, C extends B> C copyProperties(B a, C b) {
		for (Field field : getAllFields(a.getClass())) {
			if (isStatic(field.getModifiers()))
				continue;
			try {
				field.setAccessible(true);
				field.set(b, field.get(a));
