            default:
                notBars = Collections.unmodifiableList(new ArrayList(this.notBars));
            }

            return new SomePojo(this.notFoos, notBars);
        }

        public String toString() {
            return "SomePojo.SomePojoBuilder(notFoos=" + this.notFoos + ", notBars=" + this.notBars + ")";
