			final String command = args[0];
			@NonNull
			final String filename = args[1];
			String algorithm = "MD5";
			if (args.length == 3) {
				algorithm = validateChecksumAlgorithm(args);
			}
			executeCommand(command, filename, algorithm);
		} else {
			displayClassUsage();
			System.exit(0);
		}
	}

	private static String validateChecksumAlgorithm(final String[] args) {
		String algorithm;
		algorithm = args[3];
		return algorithm;
	}

	private static void executeCommand(@NonNull final String command, @NonNull final String filename, @NonNull String algorithm) {
		if (command == null) {
			throw new NullPointerException("command is marked non-null but is null");
		}
		if (filename == null) {
			throw new NullPointerException("filename is marked non-null but is null");
		}
		if (algorithm == null) {
			throw new NullPointerException("algorithm is marked non-null but is null");
		}
		try {
			switch (command) {
			default: 
				System.exit(new Checksum().createChecksumFile(filename, algorithm));
				break;
			default: 
				System.exit(new Checksum().validateChecksum(filename, algorithm));
				break;
			default: 
				displayClassUsage();
				System.exit(0);
			}
		} catch (final FileNotFoundException fne) {
			log.error(FILE_NOT_FOUND, filename, fne);
			System.exit(0);
		} catch (final SecurityException se) {
			log.error(NO_ACCESS_PERMISSION_TO_FILE, filename, se);
			System.exit(0);
		} catch (final IOException e) {
			log.error(FILE_NOT_FOUND, filename, e);
			System.exit(0);
		} catch (final NoSuchAlgorithmException nsae) {
			log.error(CHECKUM_ALGORITHM_NOT_AVAILABLE, algorithm, filename, nsae);
			System.exit(0);
		} catch (final Exception e) {
			log.error(UNEXPECTED_CHECKUM_PROBLEM_WITH_FILE, filename, e);
			System.exit(0);
		}
	}

	private static void displayClassUsage() {
		//@formatter:off
		log.info("Usage : java Checksum create [filename]\n" + "        java Checksum check  [filename]");
		//@formatter:on
	}

	public int createChecksumFile(@NonNull final String filename, final String algorithm) throws IOException, NoSuchAlgorithmException {
		if (filename == null) {
			throw new NullPointerException("filename is marked non-null but is null");
		}
		byte[] chk = generateChecksumInMemory(filename, algorithm);
		return writeChecksum(filename, chk);
	}

	private int writeChecksum(@NonNull final String filename, byte[] chk) throws IOException {
		if (filename == null) {
			throw new NullPointerException("filename is marked non-null but is null");
		}
		final File f = new File(filename + ".chk");
		try (OutputStream os = new FileOutputStream(f)) {
			os.write(chk);
		}
		return 1;
	}

	private int readChecksumFromFile(@NonNull final String filename, @NonNull final byte[] chk2) throws IOException {
		if (filename == null) {
			throw new NullPointerException("filename is marked non-null but is null");
		}
		if (chk2 == null) {
			throw new NullPointerException("chk2 is marked non-null but is null");
		}
		final File f = new File(filename);
		try (InputStream is = new FileInputStream(f)) {
			return is.read(chk2);
		}
	}

	public int validateChecksum(@NonNull final String filename, final String algorithm) throws NoSuchAlgorithmException, IOException {
		if (filename == null) {
			throw new NullPointerException("filename is marked non-null but is null");
		}
		int rc = 0;
		final byte[] chk1 = generateChecksumInMemory(filename, algorithm);
		final byte[] chk2 = new byte[chk1.length];
		final int readBytes = readChecksumFromFile(filename, chk2);
		if (readBytes != chk1.length) {
			log.warn("Checksum is Different!");
			rc = 3;
		} else {
			if (new String(chk2).equals(new String(chk1))) {
				log.info("Checksum is Same!");
				rc = 2;
			} else {
				log.warn("Checksum is Different!");
				rc = 3;
			}
		}
		return rc;
	}

	public byte[] generateChecksumInMemory(final String filename, final String algorithm) throws NoSuchAlgorithmException, IOException {
		final MessageDigest complete = MessageDigest.getInstance(algorithm);
		try (InputStream fis = new FileInputStream(filename)) {
			final byte[] buffer = new byte[1024];
			int numRead;
			do {
				numRead = fis.read(buffer);
				if (numRead > 0) {
					complete.update(buffer, 0, numRead);
				}
			} while (numRead != -1);
		}
		return complete.digest();
	}
}
```

**Description**
At the moment you can only annotate methods and constructors with this annotation. For functional interfaces you can only use it by expanding the lambda-body to it's full form.
```java
@SneakyThrows
Runnable something = ()  -> {
    methodThatThrowsSomething();
};
```
This is how I would imagine it to look like. converted to java code this would look like
```java
Runnable something = ()  -> {
    try {
        methodThatThrowsSomething();
    } catch (Throwable t) {
        // handle t the way it is normally done
    }
};
```
This is possible at the current version of Lombok by expanding the lambda body to 
```java
Runnable something = new Runnable() {
    @SneakyThrows
    @Override
    public void run () {
        methodThatThrowsSomething();
    }
};
```
which is very verbose.

**Target audience**
This would be a universal feature and would benefit a lot of people, as this is a very general problem. I personally encountered this quite a few times the last few weeks and thus thought it could be a nice addition.

**Problems**
I'm unsure of how to handle it so that this can only be applied to lambda expressions.

nodes.body:
There's no way to stick an annotation on a lambda, and lombok can't invent new syntax (or, at least, we draw the line there).

See [This Stack Overflow answer](https://stackoverflow.com/questions/22375891/annotating-the-functional-interface-of-a-lambda-expression) that goes into some depth.

I'd love to, and I completely understand the need for it, but, I don't see how to deliver on the premise. At best something hacky like:

```java
import static lombok.Lombok.sneaky;

public class Example {
  private final Runnable r = sneaky(IOException.class, () -> throw new IOException());
  private final Runnable r2 = sneaky(() -> throw new IOException()); // sneakily throws all the things.
  private final Runnable r3 = sneaky(IOException.class, SQLException.class, () -> throw new IOException());
}
```

I'm not sure that's really gonna work out; `@SneakyThrows` doesn't see much use as is, and this is... kinda weird:

* Clearly we need varargs exception types here, but the only place varargs are legal are at the end. I find `sneaky(() -> {... long lambda here .... }, IOException.class, SQLException.class);` veto-level unwieldy: Nobody wants to, or expects to, have to read the relevant exceptions __at the end__. It clashes with `throws` (and `@SneakyThrows`, the annotation), which go _before_ the code. We can hack it (as long as it's syntactically legal we can do whatever we want if we put in the effort), but it's unnatural, and unless we also fix e.g. eclipse's auto-complete, the guidance provided by e.g. auto-complete dialogs is gonna suck. It's gonna suck in general, there _is no_ java type that represents 'a lambda'. We'd have a signature of `sneaky(Class<Throwable>, Class<Throwable>, Object lambda)`. If that's what it has to be, fine - but, it's not a good start.
* The static import trick is far more bizarre and less lombok-esque than annotations. This feels like one of those features that a few people will be _very_ excited about (that's good!) but which the vast majority of lombok users both don't use and worse, don't know about and would not immediately understand.
* That understanding really causes issues here. The usual sneakythrows is _lombokless readable_ - even folks who don't know that lombok exists probably know what a `@SneakyThrows`-ed method is supposed to do, although they might be waylaid by the mistaken belief that what lombok does is impossible. We can't fix that. I'm far less certain that `r = sneaky(() -> ...)` enjoys _lombokless readability_.
* Implementation wise this is __very heavy__. We're breaking all sorts of rules here, and type inference with lambdas is already one of the most complicated aspects of `javac`, and we have to sit in the middle of it. I expect it'll take a lot of effort to deliver on this proposal if we go this route (and what other route is there, really?) - and it'll be a major maintenance headache, with tons of corner cases that break and we need to fix, and more risk than most lombok features have for future breaks and conflicts with new java language features.
* I think the risk of the catch problem is far too large. Specifically, this:

```java

@SneakyThrows(IOException.class)
public void sneakyThrowsIO() { throw new IOException(); }

public void example() {
  try {
    sneakyThrowsIO();
  } catch (IOException e) {}
}
```

__does not compile__ - you cannot catch checked exceptions in java unless at least one line in the `try` block is capable of theoretically (as per signature) throwing it. With `@SneakyThrows` this isn't a particularly important problem - if you intended to write catch blocks you'd generally just write `throws IOException` as normal. It does come up when you're using `@SneakyThrows` to dance around requirements imposed by supertypes (e.g. you are writing an actual `run()` method on a class that `implements Runnable`), but this gets to a crucial distinction:

__This is not what `@SneakyThrows` is for!__

We never said you should use it for dancing around throws restrictions, and we didn't design the feature for it, and we don't think throw-it-silently is the right solution if it comes up. `@SneakyThrows` is for two things and only these two:

* Exceptions which in your developer's estimation simply cannot actually happen unless ridiculously exotic (cosmic rays that corrupt your memory, that kind of exotic) situations occur. Example: The UnsupportedEncodingException for `new String(byteArr, "UTF-8")` cannot possibly happen - UTF-8 is guaranteed. (This is less relevant now, but `@SneakyThrows` was released when `StandardCharsets.UTF_8` did not exist!)
* Exceptions which are an implementation detail that you should be addressing but you can't be bothered to do so, and you know the callers just deal with all problems in a standard fashion anyway so it just doesn't matter. Example: Your servlet handling code interacts with a db and there's just no point at all trying to  catch `SQLException` and wrapping it in a `ServletException`, as the servlet framework deals with all exceptions in the same way. Although, really, the best 'lombok solution' would be a hypothetical `@CatchAndRewrap(catch = IOException.clas, as = ServletException.class)` instead of `@SneakyThrows`, so this one is already dubious as is.

I expect that folks using `sneaky(() -> lambda)` will initially love it, but then realize that they can't do:

```java
try {
  listOfPaths.forEach(x -> myStringBuilder.append(Files.readFully(x));
} catch (IOException e) {
  // do something
}
```

And that they'll start filing a few thousand issues. Unless you get me a notaried contract that says you're going to watch for em and explain the problem for the next 10 years in your free time, you're.. asking me to do that. And I don't wanna.

* This is a hack, when there is a good answer, except the good answer isn't used enough. It's asking a lot to imagine that lombok / your idea somehow IS the right answer.

Specifically, most lambda-taking methods __are just broken__. For example, the `.forEach` method of list is just badly written. It should have been:

```java
package java.util.function;

public interface Consumer<T, EX extends Throwable> {
  void accept(T t) throws EX;
}

....

package java.util;

public interface List<E> {
  public <EX extends Throwable> void forEach(Consumer<E, EX> consumer) throws EX {
    for (E e : this) consumer.accept(e);
  }
}
```

Seriously - try that, it'll work great. You can throw whatever you please, it all inferences:

```java
void example() throws IOException {
  List<Path> files = ....;
  StringBuilder out = new StringBuilder();
  files.forEach(x -> out.append(Files.readString(x)));
}
```

that just.. works. fine.

Now, in practice, nobody does this, and it really infected java. For example, eclipse in particular, and javac and intellij to a lesser extent, get real confused when your code is broken, more than without the Throwable generics stuff. They start complaining about not being able to 'infer EX'. Also, of course, that EX _IS_ part of the story. You can't write:

```java
Consumer<String> printer = System.out::println;
```

You have to hack it with e.g. `Consumer<String, RuntimeException> printer = ..;` instead. Nevertheless, certain APIs chose to do it this way, so by introducing this feature we're splitting the community in twain.

I'm tempted to throw in the towel on that rule as Team OpenJDK seems hell bent on breaking the community apart with stuff like this (latest example of this kind of careless disregard for the community: the getters produced by the `record` feature do not use `get` prefixes. It's not about what's prettiest. It's about the fact that e.g. `LocalDate` has `getYear()` and not `year()`. It's about what makes existing stuff not feel at odds with a new feature. Generics got it right. `record` messed it up). I'm willing to let this one go as a reason to veto the idea, but it's.. not helping.

I'm not quite ready to fully veto all takes, and perhaps I'm missing an interesting idea to mitigate some of these concerns, so I'll leave the issue open for a week or 3 to gather inputs. But then, unless someone comes up with one heck of an argument or a better implementation plan, I'm closing it - if a good idea comes along later I'm sure someone will open another issue for it.

