    public boolean setA(A a) {  
        if (this.a.equals(a)) return false;  
        if (this.a != null) this.a.getBsModifiable$lombok().remove(this);  
        if (a != null) a.getBsModifiable$lombok().add(this);  
        this.a = a;  
        return true;  
    }  
      
    public A getA() {  
        return a;  
    }  
}
