```
import org.eclipse.jdt.annotation.NonNull;

public class Bar {
    public static @NonNull BarBuilder<@NonNull ?, ?> builder() {
        return new BarBuilderImpl();
    }
    
    public void doIt() {
        
    }

    public static abstract class BarBuilder<C extends Bar, B extends Bar.BarBuilder<C, B>> {
        public abstract C build();

    }

    private static class BarBuilderImpl extends BarBuilder<@NonNull Bar, BarBuilderImpl> {
        public Bar build() {
            return new Bar();
        }
    }
}
```

