**To Reproduce**

```java
interface LombokInterface {

    ThreadLocal<Boolean> GETTER_INVOKED = new ThreadLocal<>();

    ThreadLocal<Boolean> SETTER_INVOKED = new ThreadLocal<>();

    default String getName() {
        try {
            var field = getClass().getDeclaredField("name");
            if (!field.canAccess(this)) {
                field.setAccessible(true);
            }
            var name = (String) field.get(this);
            GETTER_INVOKED.set(Boolean.TRUE);
            return name;
        } catch (ReflectiveOperationException roe) {
            throw new RuntimeException(roe);
        }
    }

    default void setName(final String name) {
        try {
            var field = getClass().getDeclaredField("name");
            if (!field.canAccess(this)) {
