}

public abstract class BaseService<B extends Base.BaseBuilder<?, ?>> {
    protected abstract B createBuilder();

    public B newBuilder() {
        return createBuilder()
                .base(true);
    }
}

public class DerivedService extends BaseService<Derived.DerivedBuilder<?, ?>> {
